**lib/risk.js** — 纯函数决策引擎：

```js
export const LEVELS = ["low", "medium", "high", "critical"];
export const LEVEL_RANK = Object.freeze({ low: 0, medium: 1, high: 2, critical: 3 });

export function compilePatterns(patterns) {
  return (patterns ?? []).map((p) => new RegExp(p, "i"));
}

export function rankOf(level) { return LEVEL_RANK[level] ?? 0; }

export function matchRules(command, rules) {
  const hits = [];
  for (const rule of rules) {
    try {
      if (rule.pattern.test(command)) hits.push(rule);
    } catch { /* 忽略损坏的正则 */ }
  }
  hits.sort((a, b) => rankOf(b.level) - rankOf(a.level));
  return hits;
}

export function decideCommand(command, options) {
  const { rules, allowPatterns = [], askMinLevel = "high", denyMinLevel = "critical", llmDecision } = options;
  if (allowPatterns.length > 0 && allowPatterns.some((re) => re.test(command))) {
    return { kind: "allow", level: "low", source: "allowlist" };
  }
  const hits = matchRules(command, rules);
  const top = hits[0];
  if (top === undefined) {
    if (llmDecision !== undefined) return { ...llmDecision, source: "llm" };
    return { kind: "allow", level: "low", source: "default" };
  }
  const rank = rankOf(top.level);
  if (rank >= rankOf(denyMinLevel)) return { kind: "deny", level: top.level, rule: top, source: "rules" };
  if (rank >= rankOf(askMinLevel)) return { kind: "ask", level: top.level, rule: top, source: "rules" };
  return { kind: "allow", level: top.level, rule: top, source: "rules" };
}
```

