{"content": "// 命令风险决策引擎（纯函数，不依赖 cordis，可独立测试）。
import { LEVEL_RANK } from "./rules.js";

/**
 * 把配置中的字符串正则编译为 RegExp。
 * 编译失败（非法正则）时跳过并返回 null，避免一条坏规则拖垮整个插件。
 * @param {string} pattern
 * @returns {RegExp | null}
 */
export function compilePattern(pattern) {
  try {
    return new RegExp(pattern, "i");
  } catch {
    return null;
  }
}

/** 编译一组字符串正则，过滤掉非法项。 */
export function compilePatterns(patterns) {
  return (patterns ?? [])
    .map((pattern) => (typeof pattern === "string" ? compilePattern(pattern) : null))
    .filter((regex) => regex !== null);
}

/**
 * 编译规则列表：把字符串 pattern 转成 RegExp。
 * 每条规则还会被冻结，避免运行期意外修改。
 * @param {Array<{ id: string; level: string; pattern: string; description?: string; hint?: string }>} rules
 * @returns {Array<{ id: string; level: string; pattern: RegExp; description?: string; hint?: string }>}
 */
export function compileRules(rules) {
  const compiled = [];
  for (const rule of rules ?? []) {
    if (typeof rule?.pattern !== "string") continue;
    const regex = compilePattern(rule.pattern);
    if (regex === null) continue;
    compiled.push(Object.freeze({ ...rule, pattern: regex }));
  }
  return compiled;
}

/** 命中一条命令的所有规则，按级别降序、规则顺序稳定。 */
export function matchRules(command, rules) {
  const hits = [];
  for (const rule of rules) {
    try {
      rule.pattern.lastIndex = 0;
      if (rule.pattern.test(command)) hits.push(rule);
    } catch {
      // 单个规则执行异常不影响整体审核
    }
  }
  hits.sort((a, b) => LEVEL_RANK[b.level] - LEVEL_RANK[a.level]);
  return hits;
}

/**
 * 对一条命令做出审核决策。
 *
 * 优先级（从高到低）：
