{"content": "// dsh-command-guard 插件入口。
//
// 能力：监听 `tools/pre-execute` waterfall，在 agent 调用 shell 类工具
// （默认 pwsh / bash）之前自动审核 `command` 参数：
//   - 命中 critical 规则           → { kind: "deny" } 直接拒绝，模型看到原因后可调整
//   - 命中 high 规则               → { kind: "ask"  } 走 harness 的 approval seam
//                                    （web/terminal UI 原生弹出批准询问）
//   - 白名单 / medium / 未命中规则 → { kind: "allow" } 放行（继续执行后续监听器）
//
// `ask` 依赖 `ctx.approval`（dsh-user-approval，dsh-base 默认装载）：
// 用户批准 → allowed-once 放行本次调用；拒绝 → 模型收到 "the user rejected ..."。
// 若部署中没有 approval 服务，ask 由平台降级为 deny（fail closed）。
import z from "@deepseek-ai/schemastery";
import { DEFAULT_ALLOW_COMMANDS, DEFAULT_RULES } from "./rules.js";
import { compilePatterns, compileRules, decideCommand, previewCommand } from "./risk.js";
import { reviewWithLlm } from "./llm.js";

export const name = "command-guard";
export const inject = ["tools"];

/** 运行配置。 */
export const Config = z.object({
  /** 总开关。 */
  enabled: z.boolean().default(true),
  /** 要审核的工具名列表。 */
  tools: z.array(z.string()).default(["pwsh", "bash"]),
  /** 额外白名单（字符串正则，忽略大小写），与默认白名单合并。 */
  allowCommands: z.array(z.string()).default([]),
  /** 额外风险规则（追加到默认规则之后），字段同默认规则。 */
  rules: z.array(z.object({
    id: z.string(),
    level: z.union(["low", "medium", "high", "critical"]),
    pattern: z.string(),
    description: z.string(),
    hint: z.string(),
  })).default([]),
  /** 禁用的默认规则 id。 */
  disabledRuleIds: z.array(z.string()).default([]),
  /** 触发用户询问的最低级别。 */
  askMinLevel: z.union(["low", "medium", "high", "critical"]).default("high"),
  /** 触发直接拒绝的最低级别。 */
  denyMinLevel: z.union(["low", "medium", "high", "critical"]).default("critical"),
  /** 是否把每次审核决策写入日志。 */
  logDecisions: z.boolean().default(true),
  /** 命令预览的最大字节数（用于提示与日志）。 */
  maxCommandPreviewBytes: z.number().min(16).default(300),
  /** 可选 LLM 审核（对未命中规则的命令分类）。 */
  llm: z.object({
    enabled: z.boolean().default(false),
    /** 审核用 provider；缺省取调用 agent 的 provider。 */
    provider: z.string(),
    /** 审核用 model；缺省取调用 agent 的 model。 */
    model: z.string(),
    /** 单次审核超时（毫秒）。 */
    timeoutMs: z.number().default(15000),
    /** 审核失败（超时/异常）时是否放行；false 则降级为 ask。 */
    allowOnFailure: z.boolean().default(true),
  }).default({}),
});

export function apply(ctx, config) {
  if (!config.enabled) return;

  const defaultRules = DEFAULT_RULES.filter((rule) => !config.disabledRuleIds.includes(rule.id));
  const rules = compileRules([...defaultRules, ...config.rules]);
  const allowPatterns = compilePatterns([...DEFAULT_ALLOW_COMMANDS, ...config.allowCommands]);

  if (rules.length === 0 && allowPatterns.length === 0) {
    ctx.logger.warn("[command-guard] 没有可用的规则与白名单，插件不生效；请检查 disabledRuleIds / rules / allowCommands 配置");
  }

  const log = (level, message, meta) => {
    if (!config.logDecisions) return;
    ctx.logger[level](`[command-guard] ${message}`, meta ?? "");
  };

  ctx.on("tools/pre-execute", async (exec, next) => {
    // 只审核配置中的工具
    if (!config.tools.includes(exec.name)) return next();
    // 只审核带 command 字符串参数的工具调用
    const command = exec.arguments?.command;
    if (typeof command !== "string" || command.trim().length === 0) return next();

    const preview = previewCommand(command, config.maxCommandPreviewBytes);

    // 可选 LLM 审核：仅对未命中规则（先跑规则，LLM 决策作为兜底）
    let llmDecision;
    if (config.llm.enabled) {
      llmDecision = await reviewWithLlm(ctx, exec, command, config.llm).catch((error) => {
        ctx.logger.warn(`[command-guard] LLM 审核失败：${error?.message ?? error}`);
        return undefined;
      });
    }

    const decision = decideCommand(command, {
      rules,
      allowPatterns,
      askMinLevel: config.askMinLevel,
      denyMinLevel: config.denyMinLevel,
      llmDecision,
    });

    switch (decision.kind) {
      case "allow": {
        log("info", `allow  ${exec.name} ${JSON.stringify(preview)}（${decision.source}${decision.rule ? `:${decision.rule.id}` : ""}）`);
        return next();
      }
      case "ask": {
        const reason = `命令审核：${decision.reason}。命令：${JSON.stringify(preview)}。请确认是否允许执行。`;
        log("warn", `ask   ${exec.name} ${JSON.stringify(preview)}（${decision.rule?.id ?? "llm"}）`);
        return { kind: "ask", reason };
      }
      case "deny": {
        const reason = `命令审核拒绝：${decision.reason}。命令：${JSON.stringify(preview)}。`;
        log("warn", `deny  ${exec.name} ${JSON.stringify(preview)}（${decision.rule?.id ?? "llm"}）`);
        return { kind: "deny", reason };
      }
      /* c8 ignore next 2 -- closed union */
      default:
        return next();
    }
  });
}
", "file_path": "G:\dsh-dev\plugins\dsh-command-guard\lib\index.js"}

