// 默认关闭；开启后每次未命中规则的命令都会产生一次模型调用（延迟与成本）。
import { createUserMessage } from "@deepseek-ai/dsh-llm";

const SYSTEM_PROMPT = "你是命令安全审核器。只输出 JSON，不要输出其他任何内容。";

/**
 * 构造审核 prompt。
 * @param {string} command 待审核命令
 * @param {string} toolName 工具名
 */
export function buildReviewPrompt(command, toolName) {
  return [
    `请判断以下通过 \`${toolName}\` 工具执行的命令是否高风险。`,
    "高风险包括：删除/覆盖数据、格式化磁盘、修改权限或账户、关闭安全防护、下载并执行远程脚本、改写 git 历史、无 WHERE 的数据库写操作等。",
    "若命令明显无害（只读、查询、常规构建/安装到当前项目），判定为 allow。",
    "若命令有破坏性或不可逆副作用、但可能是合法意图，判定为 ask（需要用户确认）。",
    "若命令几乎不可能是合法意图（删除根目录、关闭杀毒、格式化磁盘等），判定为 deny。",
    "",
    `命令：\`\`\`\n${command}\n\`\`\``,
    "",
    '输出 JSON：{"verdict":"allow"|"ask"|"deny","reason":"一句话中文理由"}',
  ].join("\n");
}

/** 从模型输出中解析 verdict。 */
export function parseVerdict(text) {
  const trimmed = (text ?? "").trim();
  try {
    const parsed = JSON.parse(trimmed);
    if (parsed && typeof parsed === "object") {
      const kind = typeof parsed.verdict === "string" ? parsed.verdict.toLowerCase() : "";
      const reason = typeof parsed.reason === "string" ? parsed.reason : "";
      if (kind === "allow" || kind === "ask" || kind === "deny") {
        return { kind, reason };
      }
    }
  } catch {
    // 模型没有输出合法 JSON，走关键词扫描
  }
  const lower = trimmed.toLowerCase();
  if (/\bdeny\b/.test(lower) && !/\ballow\b/.test(lower)) return { kind: "deny", reason: "LLM 判定为拒绝" };
  if (/\bask\b/.test(lower)) return { kind: "ask", reason: "LLM 判定需要确认" };
  if (/\ballow\b/.test(lower)) return { kind: "allow", reason: "LLM 判定安全" };
  return undefined;
}

/**
 * 用 LLM 审核一条命令。
 * @param {import("@deepseek-ai/cordis").Context} ctx
 * @param {object} exec tools/pre-execute 的 exec
 * @param {string} command 待审核命令
 * @param {object} llmConfig 插件 llm 配置
 * @returns {Promise<{ kind: "allow"|"ask"|"deny", reason: string } | undefined>}
 *   无法解析 provider/model、无 llm 服务或解析失败时返回 undefined。
 */
export async function reviewWithLlm(ctx, exec, command, llmConfig) {
  const llm = ctx.get("llm");
  if (llm === void 0) return undefined;

  const agentOptions = exec.agent?.options;
  const provider = llmConfig.provider ?? agentOptions?.provider;
  const model = llmConfig.model ?? agentOptions?.model;
  if (typeof provider !== "string" || typeof model !== "string") return undefined;

  const timeoutMs = Number.isFinite(llmConfig.timeoutMs) ? llmConfig.timeoutMs : 15000;
  const timeoutController = new AbortController();
  const timer = setTimeout(() => timeoutController.abort(), timeoutMs);
  const onExecAbort = () => timeoutController.abort();
  if (exec.signal?.aborted) timeoutController.abort();
  else exec.signal?.addEventListener("abort", onExecAbort, { once: true });

  try {
    const userMessage = createUserMessage({
      content: [{ type: "text", text: buildReviewPrompt(command, exec.name) }],
      source: { kind: "plugin", plugin: "command-guard", form: "notice", summary: "命令安全审核" },
    });

    let text = "";
    const stream = llm.stream({
      provider,
      model,
      system: SYSTEM_PROMPT,
      messages: [userMessage],
      temperature: 0,
      maxTokens: 128,
      stop: ["\n\n"],
      signal: timeoutController.signal,
    });
    for await (const chunk of stream) {
      if (chunk.type === "text-delta") text += chunk.text;
      if (chunk.type === "finish") break;
    }
    return parseVerdict(text);
  } finally {
    clearTimeout(timer);
    exec.signal?.removeEventListener("abort", onExecAbort);
  }
}
