function quietLogger() {
  return {
    info() {},
    warn() {},
    debug() {},
    error() {},
    success() {},
    level: 3,
  };
}

async function load(config) {
  const ctx = new Context();
  ctx.provide("tools", { register() {} });
  ctx.logger = quietLogger();
  await ctx.plugin(plugin, config);
  return ctx;
}

async function run(ctx, exec) {
  return ctx.waterfall(ctx, "tools/pre-execute", exec, () => Promise.resolve({ kind: "allow" }));
}

test("加载插件后可正常导出", async () => {
  assert.equal(plugin.name, "command-guard");
  assert.equal(typeof plugin.apply, "function");
  assert.deepEqual(plugin.inject, ["tools"]);
});

test("critical 命令 → deny，reason 包含命令", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh", "bash"] });
  const decision = await run(ctx, makeExec({ arguments: { command: "rm -rf /", description: "x" } }));
  assert.equal(decision.kind, "deny");
  assert.match(decision.reason, /rm -rf \//);
  assert.match(decision.reason, /命令审核拒绝/);
});

test("high 命令 → ask，reason 包含命令", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh"] });
  const decision = await run(ctx, makeExec({ arguments: { command: "Remove-Item src/main.js", description: "x" } }));
  assert.equal(decision.kind, "ask");
  assert.match(decision.reason, /Remove-Item src\/main\.js/);
  assert.match(decision.reason, /请确认是否允许执行/);
});

test("安全命令 → allow（调用 next）", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh"] });
  const decision = await run(ctx, makeExec({ arguments: { command: "Get-ChildItem", description: "x" } }));
  assert.equal(decision.kind, "allow");
});

test("未在 tools 列表中的工具 → 不审核", async () => {
  const ctx = await load({ enabled: true, tools: ["bash"] });
  const decision = await run(ctx, makeExec({ name: "pwsh", arguments: { command: "rm -rf /", description: "x" } }));
  assert.equal(decision.kind, "allow");
});

test("无 command 参数的工具调用 → 不审核", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh"] });
  const decision = await run(ctx, makeExec({ arguments: { path: "/tmp" } }));
  assert.equal(decision.kind, "allow");
});

test("enabled: false → 完全放行", async () => {
  const ctx = await load({ enabled: false, tools: ["pwsh"] });
  const decision = await run(ctx, makeExec({ arguments: { command: "rm -rf /", description: "x" } }));
  assert.equal(decision.kind, "allow");
});

test("askMinLevel 收紧：medium 命令触发 ask", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh"], askMinLevel: "medium" });
  const decision = await run(ctx, makeExec({ arguments: { command: "Get-Content .env", description: "x" } }));
  assert.equal(decision.kind, "ask");
});

test("denyMinLevel 收紧：high 命令直接拒绝", async () => {
  const ctx = await load({ enabled: true, tools: ["pwsh"], denyMinLevel: "high" });
  const decision = await run(ctx, makeExec({ arguments: { command: "rm -rf node_modules", description: "x" } }));
  assert.equal(decision.kind, "deny");
});

